resource "aws_route53_health_check" "primary" {
  fqdn              = "ingest-primary.us-east-1.example.com"
  port              = 443
  type              = "HTTPS"
  resource_path     = "/healthz"
  failure_threshold = 3
  request_interval  = 10
  tags = { Name = "ingest-primary-health" }
}

resource "aws_route53_record" "primary" {
  zone_id        = var.zone_id
  name           = "ingest.example.com"
  type           = "A"
  set_identifier = "primary-us-east-1"

  failover_routing_policy {
    type = "PRIMARY"
  }
  health_check_id = aws_route53_health_check.primary.id

  alias {
    name                   = aws_lb.primary.dns_name
    zone_id                = aws_lb.primary.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "secondary" {
  zone_id        = var.zone_id
  name           = "ingest.example.com"
  type           = "A"
  set_identifier = "secondary-us-west-2"

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = aws_lb.secondary.dns_name
    zone_id                = aws_lb.secondary.zone_id
    evaluate_target_health = true
  }
}

resource "aws_s3_bucket" "primary" {
  bucket = "lake-primary-use1"
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket" "dr" {
  provider = aws.usw2
  bucket   = "lake-dr-usw2"
}

resource "aws_s3_bucket_versioning" "dr" {
  provider = aws.usw2
  bucket   = aws_s3_bucket.dr.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_replication_configuration" "crr" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-lake"
    status = "Enabled"
    filter { prefix = "warehouse/" }

    destination {
      bucket        = aws_s3_bucket.dr.arn
      storage_class = "STANDARD_IA"
      # RTC gives a 15-minute replication SLA with metrics + events
      replication_time { status = "Enabled"; time { minutes = 15 } }
      metrics         { status = "Enabled"; event_threshold { minutes = 15 } }
    }
    delete_marker_replication { status = "Enabled" }
  }
  depends_on = [aws_s3_bucket_versioning.primary]
}
